import android.view.accessibility.AccessibilityNodeInfo
import com.rotametric.app.core.model.NodeSnapshot

/**
 * Converte AccessibilityNodeInfo em NodeSnapshot imutável.
 * Limita profundidade e quantidade de nós para evitar custo excessivo.
 * Filtra classes de entrada de texto (EditText) para não ler campos editáveis.
 */
object AccessibilityNodeReader {
    private const val MAX_DEPTH = 18
    private const val MAX_NODES = 400

    fun snapshot(root: AccessibilityNodeInfo?): NodeSnapshot? {
        root ?: return null
        var count = 0
        fun walk(node: AccessibilityNodeInfo, depth: Int): NodeSnapshot? {
            if (depth > MAX_DEPTH || count >= MAX_NODES) return null
            count++
            val className = node.className?.toString()
            val isEditable = node.isEditable || className?.contains("EditText") == true
            val text = if (isEditable || node.isPassword) null else node.text?.toString()
            val desc = if (isEditable) null else node.contentDescription?.toString()
            val children = ArrayList<NodeSnapshot>(node.childCount)
            for (i in 0 until node.childCount) {
                val child = node.getChild(i) ?: continue
                walk(child, depth + 1)?.let(children::add)
                child.recycle()
            }
            return NodeSnapshot(
                text = text,
                contentDescription = desc,
                viewId = node.viewIdResourceName,
                className = className,
                children = children
            )
        }
        return walk(root, 0)
    }
}

package com.rotametric.app.core.parser

import java.util.Locale

/**
 * Normaliza textos de tela em números. Puro Kotlin, testável.
 */
object RideDataNormalizer {

    private val currencyRegex = Regex("""R\$\s*(\d{1,4}(?:[.,]\d{3})*(?:[.,]\d{1,2})?)""")
    private val plainNumberRegex = Regex("""(?<![\d,.])(\d{1,4}(?:[.,]\d{3})*(?:[.,]\d{1,2})?)(?![\d,.])""")
    private val distanceRegex = Regex("""(\d+(?:[.,]\d+)?)\s*(km|m)\b""", RegexOption.IGNORE_CASE)
    private val hourMinRegex = Regex("""(\d+)\s*h(?:ora)?s?\s*(?:e\s*)?(\d+)?\s*(?:min)?""", RegexOption.IGNORE_CASE)
    private val minRegex = Regex("""(\d+(?:[.,]\d+)?)\s*min""", RegexOption.IGNORE_CASE)

    const val MIN_VALUE = 1.0
    const val MAX_VALUE = 2000.0
    const val MIN_DISTANCE_KM = 0.05
    const val MAX_DISTANCE_KM = 500.0
    const val MIN_TIME_MIN = 0.5
    const val MAX_TIME_MIN = 600.0

    fun normalizeText(raw: String): String =
        raw.replace('\u00A0', ' ').replace(Regex("\\s+"), " ").trim()

    /** "R$ 12,34" | "12,34" | "12.34" | "R$12,34" | "1.234,56" → Double */
    fun parseCurrency(text: String): Double? {
        val t = normalizeText(text)
        val match = currencyRegex.find(t) ?: plainNumberRegex.find(t) ?: return null
        val number = toDouble(match.groupValues[1]) ?: return null
        return number.takeIf { it in MIN_VALUE..MAX_VALUE }
    }

    /** "1,2 km" | "800 m" | "2.5 km" → km */
    fun parseDistanceKm(text: String): Double? {
        val t = normalizeText(text)
        val match = distanceRegex.find(t) ?: return null
        val number = toDouble(match.groupValues[1]) ?: return null
        val km = if (match.groupValues[2].lowercase(Locale.ROOT) == "m") number / 1000.0 else number
        return km.takeIf { it in MIN_DISTANCE_KM..MAX_DISTANCE_KM }
    }

    /** "5 min" | "1h 10min" | "70 min" | "1h" → minutos */
    fun parseMinutes(text: String): Double? {
        val t = normalizeText(text)
        hourMinRegex.find(t)?.let { m ->
            val hours = m.groupValues[1].toDoubleOrNull() ?: return@let
            val mins = m.groupValues[2].toDoubleOrNull() ?: 0.0
            val total = hours * 60 + mins
            return total.takeIf { it in MIN_TIME_MIN..MAX_TIME_MIN }
        }
        minRegex.find(t)?.let { m ->
            val mins = toDouble(m.groupValues[1]) ?: return@let
            return mins.takeIf { it in MIN_TIME_MIN..MAX_TIME_MIN }
        }
        return null
    }

    fun containsCurrency(text: String): Boolean = currencyRegex.containsMatchIn(text)
    fun containsDistance(text: String): Boolean = distanceRegex.containsMatchIn(text)
    fun containsTime(text: String): Boolean = minRegex.containsMatchIn(text) || hourMinRegex.containsMatchIn(text)

    /**
     * Converte "1.234,56" / "1,234.56" / "12,34" / "12.34" para Double.
     */
    fun toDouble(raw: String): Double? {
        val s = raw.trim()
        if (s.isEmpty()) return null
        val hasComma = s.contains(',')
        val hasDot = s.contains('.')
        val normalized = when {
            hasComma && hasDot -> {
                if (s.lastIndexOf(',') > s.lastIndexOf('.')) s.replace(".", "").replace(',', '.')
                else s.replace(",", "")
            }
            hasComma -> {
                val afterComma = s.substringAfterLast(',')
                if (afterComma.length == 3 && s.count { it == ',' } == 1 && s.substringBefore(',').length <= 3 && !s.startsWith("0"))
                    s.replace(",", "") // 1,234 = milhar
                else s.replace(',', '.')
            }
            hasDot -> {
                val afterDot = s.substringAfterLast('.')
                if (afterDot.length == 3 && s.count { it == '.' } == 1 && s.substringBefore('.').length <= 3)
                    s.replace(".", "") // 1.234 = milhar
                else s
            }
            else -> s
        }
        return normalized.toDoubleOrNull()
    }
}

package com.rotametric.app.core.parser

import com.rotametric.app.core.model.AppSource
import com.rotametric.app.core.model.NodeSnapshot
import com.rotametric.app.core.model.ParseResult
import com.rotametric.app.core.model.RideOffer

interface RideParser {
    val source: AppSource
    fun parse(root: NodeSnapshot, timestamp: Long = System.currentTimeMillis()): ParseResult
}

/**
 * Lógica compartilhada entre parsers: varre textos, identifica valor, distâncias e tempos
 * por heurística de palavras-chave e ordem de aparição.
 */
abstract class BaseRideParser : RideParser {

    protected abstract val pickupKeywords: List<String>
    protected abstract val tripKeywords: List<String>
    protected abstract val offerMarkers: List<String>

    override fun parse(root: NodeSnapshot, timestamp: Long): ParseResult {
        val texts = root.allTexts().map(RideDataNormalizer::normalizeText).filter { it.isNotBlank() }
        if (texts.isEmpty()) return ParseResult.NoOffer("Tela vazia")

        val joined = texts.joinToString(" | ")
        val lower = joined.lowercase()
        val looksLikeOffer = offerMarkers.any { lower.contains(it) } || RideDataNormalizer.containsCurrency(joined)
        if (!looksLikeOffer) return ParseResult.NoOffer("Nenhum marcador de oferta")

        val value = texts.firstNotNullOfOrNull { t -> if (RideDataNormalizer.containsCurrency(t)) RideDataNormalizer.parseCurrency(t) else null }

        val distances = mutableListOf<Pair<Double, String>>()
        val times = mutableListOf<Pair<Double, String>>()
        texts.forEach { t ->
            RideDataNormalizer.parseDistanceKm(t)?.let { distances += it to t.lowercase() }
            RideDataNormalizer.parseMinutes(t)?.let { times += it to t.lowercase() }
        }

        val (pickupDist, tripDist) = split(distances)
        val (pickupTime, tripTime) = split(times)

        if (value == null && distances.isEmpty() && times.isEmpty()) {
            return ParseResult.NoOffer("Nenhum campo numérico reconhecido")
        }

        val offer = RideOffer(
            source = source,
            detectedAt = timestamp,
            offeredValue = value,
            pickupDistanceKm = pickupDist,
            tripDistanceKm = tripDist,
            pickupTimeMinutes = pickupTime,
            tripTimeMinutes = tripTime,
            rawTextSummary = joined.take(300)
        )

        val confidence = ParserConfidence.score(
            hasValue = value != null,
            hasTripDistance = tripDist != null,
            hasPickupDistance = pickupDist != null,
            hasTripTime = tripTime != null,
            hasPickupTime = pickupTime != null
        )

        val missing = buildList {
            if (value == null) add("valor")
            if (tripDist == null) add("distância da viagem")
            if (tripTime == null) add("tempo da viagem")
        }

        return if (missing.isEmpty() && confidence >= ParserConfidence.HIGH) ParseResult.Success(offer, confidence)
        else ParseResult.Partial(offer, confidence, missing)
    }

    /**
     * Separa pares (valor, textoOrigem) em (pickup, trip) usando palavras-chave;
     * sem palavras-chave assume ordem: primeiro = busca, segundo = viagem.
     */
    private fun split(items: List<Pair<Double, String>>): Pair<Double?, Double?> {
        if (items.isEmpty()) return null to null
        val pickup = items.firstOrNull { p -> pickupKeywords.any { p.second.contains(it) } }?.first
        val trip = items.firstOrNull { p -> tripKeywords.any { p.second.contains(it) } }?.first
        if (pickup != null || trip != null) {
            val remaining = items.map { it.first }.filter { it != pickup && it != trip }
            return (pickup ?: remaining.firstOrNull()) to (trip ?: remaining.lastOrNull().takeIf { pickup != null })
        }
        return when (items.size) {
            1 -> null to items[0].first
            else -> items[0].first to items[1].first
        }
    }
}

